-- DDCNorth client portal schema (Cloudflare D1 / SQLite).
-- Times are Unix epoch milliseconds. IDs are random strings generated by the API.

-- A space is anything mounted on the domain that can be shared:
-- a deployed GitHub repo build (served from R2 at /p/<slug>/ or <slug>.<domain>).
CREATE TABLE spaces (
  id            TEXT PRIMARY KEY,
  slug          TEXT NOT NULL UNIQUE,          -- URL segment, also the R2 prefix: sites/<slug>/
  title         TEXT NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  visibility    TEXT NOT NULL DEFAULT 'private' CHECK (visibility IN ('private', 'public')),
  subdomain     INTEGER NOT NULL DEFAULT 0,    -- 1 = also served at <slug>.<PORTAL_ROOT_DOMAIN>
  repo          TEXT,                          -- informational: owner/repo it is built from
  archived_at   INTEGER,
  created_by    TEXT,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
);

-- A grant is one share: one link (and optionally a password), or a list of
-- verified emails, for one space, with its own timing rules.
CREATE TABLE grants (
  id                 TEXT PRIMARY KEY,
  space_id           TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE,
  label              TEXT NOT NULL,             -- e.g. "Client A - proposal review"
  method             TEXT NOT NULL CHECK (method IN ('link', 'password', 'email')),
  token_hash         TEXT NOT NULL UNIQUE,      -- SHA-256 of the link token (token shown once)
  password_hash      TEXT,                      -- PBKDF2 for method = 'password'
  emails             TEXT NOT NULL DEFAULT '[]',-- JSON array of emails / "@domain.com" for method = 'email'
  timer_scope        TEXT NOT NULL DEFAULT 'grant' CHECK (timer_scope IN ('grant', 'recipient')),
  starts_at          INTEGER,                   -- not available before
  activate_by        INTEGER,                   -- a new activation must happen before this
  expires_at         INTEGER,                   -- hard cutoff for everyone
  duration_minutes   INTEGER,                   -- countdown after first successful unlock
  session_minutes    INTEGER NOT NULL DEFAULT 720, -- browser session length before re-entering
  max_unlocks        INTEGER,                   -- successful unlocks (new browser sessions) allowed
  unlock_count       INTEGER NOT NULL DEFAULT 0,
  notify_on_open     INTEGER NOT NULL DEFAULT 0,
  note               TEXT NOT NULL DEFAULT '',
  revoked_at         INTEGER,
  created_by         TEXT,
  created_at         INTEGER NOT NULL,
  updated_at         INTEGER NOT NULL
);
CREATE INDEX grants_space ON grants(space_id);

-- When a countdown started. One row per grant (timer_scope = 'grant') or per
-- verified recipient email (timer_scope = 'recipient'). Never reset by clients.
CREATE TABLE activations (
  id                TEXT PRIMARY KEY,
  grant_id          TEXT NOT NULL REFERENCES grants(id) ON DELETE CASCADE,
  recipient_key     TEXT NOT NULL,              -- 'grant' or the lowercase email
  first_unlocked_at INTEGER NOT NULL,
  expires_at        INTEGER,                    -- computed once at first unlock
  UNIQUE (grant_id, recipient_key)
);

-- A browser session (HttpOnly cookie holds a random token; only its hash is stored).
CREATE TABLE sessions (
  id            TEXT PRIMARY KEY,
  token_hash    TEXT NOT NULL UNIQUE,
  email         TEXT,                           -- set once the visitor verified an email code
  created_at    INTEGER NOT NULL,
  expires_at    INTEGER NOT NULL,
  last_seen_at  INTEGER NOT NULL,
  ip            TEXT,
  country       TEXT,
  region        TEXT,
  city          TEXT,
  user_agent    TEXT,
  revoked_at    INTEGER
);

-- Which grants a browser session has unlocked, with per-grant engagement stats.
CREATE TABLE session_grants (
  session_id      TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  grant_id        TEXT NOT NULL REFERENCES grants(id) ON DELETE CASCADE,
  activation_id   TEXT NOT NULL REFERENCES activations(id) ON DELETE CASCADE,
  email           TEXT,
  created_at      INTEGER NOT NULL,
  expires_at      INTEGER NOT NULL,
  last_seen_at    INTEGER NOT NULL,
  view_count      INTEGER NOT NULL DEFAULT 0,
  active_seconds  INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (session_id, grant_id)
);
CREATE INDEX session_grants_grant ON session_grants(grant_id);

-- One-time email codes (only the hash is stored).
CREATE TABLE email_codes (
  id          TEXT PRIMARY KEY,
  email       TEXT NOT NULL,
  code_hash   TEXT NOT NULL,
  grant_id    TEXT,                             -- null = general client sign-in
  attempts    INTEGER NOT NULL DEFAULT 0,
  created_at  INTEGER NOT NULL,
  expires_at  INTEGER NOT NULL,
  consumed_at INTEGER,
  ip          TEXT
);
CREATE INDEX email_codes_email ON email_codes(email, created_at);

-- Append-only activity log.
CREATE TABLE events (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  ts          INTEGER NOT NULL,
  type        TEXT NOT NULL,   -- link_opened, unlock_ok, unlock_failed, code_sent, code_failed, signin_ok, view, denied, revoked, admin_*
  space_id    TEXT,
  grant_id    TEXT,
  session_id  TEXT,
  email       TEXT,
  path        TEXT,
  ip          TEXT,
  country     TEXT,
  region      TEXT,
  city        TEXT,
  user_agent  TEXT,
  referer     TEXT,
  detail      TEXT              -- JSON
);
CREATE INDEX events_grant ON events(grant_id, ts);
CREATE INDEX events_space ON events(space_id, ts);
CREATE INDEX events_type_ip ON events(type, ip, ts);
